41	/** Resolve a date string: today, yesterday, Nd (relative), or YYYY-MM-DD passthrough. */
42	export function resolveDate(s: string): string {
43	  if (s === 'today') return today();
44	  if (s === 'yesterday') {
45	    const d = new Date();
46	    d.setDate(d.getDate() - 1);
47	    return formatLocalDate(d);
48	  }
49	  const m = s.match(/^(\d+)d$/);
50	  if (m) {
51	    const d = new Date();
52	    d.setDate(d.getDate() - parseInt(m[1]!, 10));
53	    return formatLocalDate(d);
54	  }
55	  return s;
56	}
