70	export function dateRange(from: string, to: string): string[] {
71	  const dates: string[] = [];
72	  const start = new Date(`${from}T00:00:00`);
73	  const end   = new Date(`${to}T00:00:00`);
74	  for (const d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
75	    dates.push(formatLocalDate(d));
76	  }
77	  return dates;
