import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { execSync } from 'child_process';
import { mkdtempSync, rmSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import { ArticleDb } from '../src/db.js';
import { resolveCoverage } from '../src/coverage.js';
import { PROVIDER_NAMES } from '../src/providers/index.js';
import type { TimeRange } from '../src/types.js';

const PROJECT_ROOT = join(import.meta.dirname!, '..');
const FEEDQ_PATH = join(PROJECT_ROOT, 'scripts', 'feedq.ts');
const RUN_ID = 'coverage-test-run';

function runFeedq(args: string, outputRoot: string): string {
  return execSync(`npx tsx ${FEEDQ_PATH} ${args}`, {
    cwd: PROJECT_ROOT,
    encoding: 'utf-8',
    timeout: 15_000,
    env: { ...process.env, FEEDQ_OUTPUT_ROOT: outputRoot },
  }).trim();
}

function makeRange(from: string, to: string): TimeRange {
  return { from: new Date(`${from}T00:00:00Z`), to: new Date(`${to}T23:59:59Z`), label: `${from}-${to}` };
}

function findProvider(coverage: Array<{ provider: string; scanned: string[]; gaps: string[] }>, provider: string) {
  const found = coverage.find(entry => entry.provider === provider);
  if (!found) throw new Error(`provider ${provider} missing from coverage`);
  return found;
}

